package com.dukaops.backend.contact; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import com.dukaops.backend.auth.*; import com.dukaops.backend.contact.dto.*; import com.dukaops.backend.tenant.TenantRepository;
@Service public class ContactService { private final CustomerRepository customers; private final SupplierRepository suppliers; private final TenantRepository tenants; public ContactService(CustomerRepository c,SupplierRepository s,TenantRepository t){customers=c;suppliers=s;tenants=t;} private void admin(TenantUserPrincipal a){if(a.getRole()!=UserRole.OWNER&&a.getRole()!=UserRole.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not have permission to manage contacts.");} private String clean(String s){return s==null||s.isBlank()?null:s.trim();}
 @Transactional(readOnly=true) public Page<ContactResponse> customers(TenantUserPrincipal a,String q,ContactStatus s,int page,int size){return customers.search(a.getTenantId(),clean(q),s,PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100))).map(this::customer);} @Transactional(readOnly=true) public Page<ContactResponse> suppliers(TenantUserPrincipal a,String q,ContactStatus s,int page,int size){return suppliers.search(a.getTenantId(),clean(q),s,PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100))).map(this::supplier);}
 @Transactional public ContactResponse createCustomer(TenantUserPrincipal a,CustomerRequest r){admin(a); String e=clean(r.email()); if(e!=null&&customers.existsByTenant_IdAndEmailIgnoreCase(a.getTenantId(),e))throw conflict(); var t=tenants.findById(a.getTenantId()).orElseThrow(); return customer(customers.save(new Customer(t,r.name().trim(),clean(r.phone()),e,clean(r.address()),clean(r.notes()))));}
 @Transactional public ContactResponse createSupplier(TenantUserPrincipal a,SupplierRequest r){admin(a); String e=clean(r.email()); if(e!=null&&suppliers.existsByTenant_IdAndEmailIgnoreCase(a.getTenantId(),e))throw conflict(); var t=tenants.findById(a.getTenantId()).orElseThrow(); return supplier(suppliers.save(new Supplier(t,r.businessName().trim(),clean(r.contactPerson()),clean(r.phone()),e,clean(r.address()),clean(r.notes()))));}
 @Transactional public ContactResponse updateCustomer(TenantUserPrincipal a,UUID id,CustomerRequest r){admin(a);var c=customers.findByTenant_IdAndId(a.getTenantId(),id).orElseThrow(()->notFound());c.update(r.name().trim(),clean(r.phone()),clean(r.email()),clean(r.address()),clean(r.notes()));return customer(c);} @Transactional public ContactResponse updateSupplier(TenantUserPrincipal a,UUID id,SupplierRequest r){admin(a);var s=suppliers.findByTenant_IdAndId(a.getTenantId(),id).orElseThrow(()->notFound());s.update(r.businessName().trim(),clean(r.contactPerson()),clean(r.phone()),clean(r.email()),clean(r.address()),clean(r.notes()));return supplier(s);}
 @Transactional public ContactResponse statusCustomer(TenantUserPrincipal a,UUID id,ContactStatus status){admin(a);var c=customers.findByTenant_IdAndId(a.getTenantId(),id).orElseThrow(()->notFound());c.setStatus(status);return customer(c);} @Transactional public ContactResponse statusSupplier(TenantUserPrincipal a,UUID id,ContactStatus status){admin(a);var s=suppliers.findByTenant_IdAndId(a.getTenantId(),id).orElseThrow(()->notFound());s.setStatus(status);return supplier(s);}
 private ContactResponse customer(Customer c){return new ContactResponse(c.getId(),c.getName(),null,null,c.getPhone(),c.getEmail(),c.getAddress(),c.getNotes(),c.getStatus(),c.getCreatedAt(),c.getUpdatedAt());} private ContactResponse supplier(Supplier s){return new ContactResponse(s.getId(),null,s.getBusinessName(),s.getContactPerson(),s.getPhone(),s.getEmail(),s.getAddress(),s.getNotes(),s.getStatus(),s.getCreatedAt(),s.getUpdatedAt());} private ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"A contact with this email already exists.");} private ResponseStatusException notFound(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Contact not found.");}}
